from __future__ import annotations
import sys
from dex.intent_trade.chains._dex_surface_flows import dex_market_observation_payload, dex_market_observation_surface_payload, dex_overview_payload, dex_quote_request_payload, dex_quote_routes_payload
_payloads = sys.modules[__name__]
def _protocols(request, protocols=None): allowed = {str(item or "").strip().lower() for item in request.flow.get("allowed_protocols") or []}; requested = [str(protocol or "").strip().lower() for protocol in (protocols or ([request.protocol] if request.protocol else [])) if str(protocol or "").strip()]; return [protocol for protocol in requested if not allowed or protocol in allowed]
def market_observation_flow(*, request, protocols=None, force_compute=False, **_): requested_protocols = _protocols(request, protocols); return _payloads.dex_market_observation_payload(chain_id=request.chain_id, protocols=requested_protocols) if force_compute else _payloads.dex_market_observation_surface_payload(chain_id=request.chain_id, protocols=requested_protocols, use_static_observation=True)
def dex_overview_flow(*, request, protocols=None, **_): return _payloads.dex_overview_payload(chain_id=request.chain_id, protocols=_protocols(request, protocols), use_static_observation=True)
def dex_quote_routes_flow(*, request, protocols=None, **kwargs): return _payloads.dex_quote_routes_payload(chain_id=request.chain_id, protocols=_protocols(request, protocols), use_static_observation=True, anchor=kwargs.get("anchor"))
def dex_quote_request_flow(*, request, protocols=None, pair=None, venue=None, amount=None, **_): requested_protocols = _protocols(request, protocols); payload = _payloads.dex_quote_request_payload(chain_id=request.chain_id, protocols=requested_protocols, pair=pair, venue=venue, amount=amount, use_static_observation=True); payload.setdefault("chain_id", request.chain_id); payload.setdefault("selected_protocols", requested_protocols); return payload
__all__ = ["dex_market_observation_payload", "dex_market_observation_surface_payload", "dex_overview_flow", "dex_overview_payload", "dex_quote_request_flow", "dex_quote_request_payload", "dex_quote_routes_flow", "dex_quote_routes_payload", "market_observation_flow"]
